/* 
  Tem Como: Joinha DS 
  Architecture: Base OKLCH Design Tokens 
*/

:root {
  color-scheme: dark;
  /* ========================================================
     1. PRIMITIVE TOKENS
     ======================================================== */

  /* --- BRAND (Hue ~53, Chroma ~0.17) --- */
  --tc-brand-50: oklch(96% 0.02 53);
  --tc-brand-100: oklch(92% 0.04 53);
  --tc-brand-200: oklch(86% 0.08 53);
  --tc-brand-300: oklch(80% 0.12 53);
  --tc-brand-400: oklch(74% 0.15 53);
  --tc-brand-500: oklch(67% 0.17 53); /* Base Brand: #e27100 */
  --tc-brand-600: oklch(58% 0.15 53);
  --tc-brand-700: oklch(48% 0.12 53);
  --tc-brand-800: oklch(38% 0.09 53);
  --tc-brand-900: oklch(28% 0.06 53);
  --tc-brand-950: oklch(18% 0.03 53);

  /* --- NEUTRALS (Hue ~53, Chroma calibrado: 0.008 a 0.014 no escuro) --- */
  /* Warm grays with perceptual brand warmth sweet spot (Four Zero Three model) */
  --tc-neutral-0: oklch(99% 0.004 53);
  --tc-neutral-50: oklch(96% 0.005 53);
  --tc-neutral-100: oklch(93% 0.006 53);
  --tc-neutral-200: oklch(88% 0.008 53);
  --tc-neutral-300: oklch(78% 0.010 53);
  --tc-neutral-400: oklch(70% 0.010 53);
  --tc-neutral-500: oklch(62% 0.012 53);
  --tc-neutral-600: oklch(50% 0.010 53);
  --tc-neutral-700: oklch(40% 0.012 53);
  --tc-neutral-800: oklch(30% 0.014 53);   /* Hover / Toast: L=30% */
  --tc-neutral-850: oklch(26% 0.014 53);   /* Modais / Diálogos: L=26% */
  --tc-neutral-900: oklch(22% 0.012 53);   /* Dropdowns / Menus: L=22% */
  --tc-neutral-950: oklch(18% 0.010 53);   /* Cards / Sidebar: L=18% */
  --tc-neutral-1000: oklch(14% 0.008 53);  /* Canvas Base: L=14% */

  /* --- STATUS: SUCCESS (Hue ~145, Muted Emerald) --- */
  --tc-success-subtle: oklch(22% 0.025 145);
  --tc-success-base: oklch(48% 0.095 145);
  --tc-success-strong: oklch(58% 0.105 145);
  --tc-success-fg: oklch(96% 0.02 145);
  --tc-success-text: oklch(82% 0.065 145);

  /* --- STATUS: WARNING (Hue ~85, Noble Amber) --- */
  --tc-warning-subtle: oklch(22% 0.025 85);
  --tc-warning-base: oklch(50% 0.105 85);
  --tc-warning-strong: oklch(60% 0.115 85);
  --tc-warning-fg: oklch(96% 0.02 85);
  --tc-warning-text: oklch(86% 0.075 85);

  /* --- STATUS: DANGER (Hue ~25, Crimson / Coral) --- */
  --tc-danger-subtle: oklch(22% 0.025 25);
  --tc-danger-base: oklch(48% 0.115 25);
  --tc-danger-strong: oklch(58% 0.125 25);
  --tc-danger-fg: oklch(96% 0.02 25);
  --tc-danger-text: oklch(84% 0.075 25);

  /* --- STATUS: INFO (Hue ~240, Slate Blue) --- */
  --tc-info-subtle: oklch(22% 0.025 240);
  --tc-info-base: oklch(48% 0.095 240);
  --tc-info-strong: oklch(58% 0.105 240);
  --tc-info-fg: oklch(96% 0.02 240);
  --tc-info-text: oklch(82% 0.065 240);

  /* --- CATEGORICAL TAGS (Low Chroma: 0.06 a 0.08) --- */
  --tc-tag-purple-subtle: oklch(22% 0.020 300);
  --tc-tag-purple-base: oklch(48% 0.085 300);
  --tc-tag-purple-fg: oklch(96% 0.02 300);
  --tc-tag-purple-text: oklch(82% 0.060 300);

  --tc-tag-pink-subtle: oklch(22% 0.020 340);
  --tc-tag-pink-base: oklch(48% 0.085 340);
  --tc-tag-pink-fg: oklch(96% 0.02 340);
  --tc-tag-pink-text: oklch(82% 0.060 340);

  --tc-tag-teal-subtle: oklch(22% 0.020 190);
  --tc-tag-teal-base: oklch(48% 0.085 190);
  --tc-tag-teal-fg: oklch(96% 0.02 190);
  --tc-tag-teal-text: oklch(82% 0.060 190);

  --tc-tag-indigo-subtle: oklch(22% 0.020 270);
  --tc-tag-indigo-base: oklch(48% 0.085 270);
  --tc-tag-indigo-fg: oklch(96% 0.02 270);
  --tc-tag-indigo-text: oklch(82% 0.060 270);

  /* --- CHARTS / DATA VIZ (Analytical Chroma Budget) --- */
  --tc-chart-1: oklch(67% 0.17 53);   /* Brand Orange Protagonist */
  --tc-chart-2: oklch(68% 0.095 190); /* Subtle Teal */
  --tc-chart-3: oklch(65% 0.095 310); /* Soft Amethyst */
  --tc-chart-4: oklch(74% 0.100 85);  /* Warm Amber */
  --tc-chart-5: oklch(65% 0.090 145); /* Muted Mint */
  --tc-chart-6: oklch(68% 0.095 260); /* Slate Cobalt */

  /* --- TYPOGRAPHY PRIMITIVES --- */
  --tc-font-display: 'Cabin', sans-serif;
  --tc-font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --tc-font-mono: 'JetBrains Mono', ui-monospace, monospace;

  --tc-font-size-100: 0.75rem;
  --tc-font-size-200: 0.875rem;
  --tc-font-size-300: 1rem;
  --tc-font-size-400: 1.125rem;
  --tc-font-size-500: 1.25rem;
  --tc-font-size-600: 1.5rem;
  --tc-font-size-700: 1.875rem;

  --tc-leading-none: 1;
  --tc-leading-tight: 1.25;
  --tc-leading-normal: 1.5;
  --tc-leading-relaxed: 1.625;

  --tc-weight-regular: 400;
  --tc-weight-medium: 500;
  --tc-weight-semibold: 600;
  --tc-weight-bold: 700;

  --tc-tracking-tighter: -0.025em;
  --tc-tracking-tight: -0.01em;
  --tc-tracking-normal: 0;
  --tc-tracking-wide: 0.025em;
  --tc-tracking-wider: 0.05em;

  /* --- SEMANTIC TYPOGRAPHY TOKENS --- */
  --type-display-metric-size: 1.875rem;
  --type-display-metric-line: 1.2;
  --type-heading-page-size: 1.5rem;
  --type-heading-page-line: 1.25;
  --type-heading-section-size: 1.25rem;
  --type-heading-section-line: 1.35;
  --type-heading-card-size: 1rem;
  --type-heading-card-line: 1.4;
  --type-body-base-size: 0.875rem;
  --type-body-base-line: 1.5;
  --type-body-sm-size: 0.8125rem;
  --type-body-sm-line: 1.5;
  --type-label-sm-size: 0.6875rem;
  --type-label-sm-line: 1.2;
  --type-label-xs-size: 0.625rem;
  --type-label-xs-line: 1.2;
  --type-code-inline-size: 0.75rem;

  /* --- SHAPES & ELEVATIONS --- */
  --tc-radius-none: 0px;
  --tc-radius-sm: 4px;
  --tc-radius-md: 6px;
  --tc-radius-lg: 8px;
  --tc-radius-xl: 12px;
  --tc-radius-2xl: 16px;
  --tc-radius-full: 9999px;

  --tc-shadow-none: 0 0 #0000;
  --tc-shadow-sm: 1px 2px 3px 0 oklch(0% 0 0 / 0.06);
  --tc-shadow-md: 2px 6px 10px -2px oklch(0% 0 0 / 0.09), 1px 3px 5px -2px oklch(0% 0 0 / 0.06);
  --tc-shadow-lg: 4px 12px 18px -3px oklch(0% 0 0 / 0.12), 2px 6px 8px -4px oklch(0% 0 0 / 0.08);
  --tc-shadow-xl: 8px 20px 30px -5px oklch(0% 0 0 / 0.16), 3px 8px 12px -6px oklch(0% 0 0 / 0.09);
  --tc-shadow-glow: 0 0 0 2px oklch(0% 0 0 / 0), 2px 6px 16px 0 var(--tc-brand-500);

  /* --- SPACING & BOX MODEL --- */
  --tc-control-h-sm: 2rem;
  --tc-control-h-md: 2.25rem;
  --tc-control-h-lg: 2.5rem;

  --tc-control-px-sm: 0.625rem;
  --tc-control-px-md: 0.75rem;
  --tc-control-px-lg: 1rem;

  --tc-floating-container-p: 0.375rem;
  --tc-floating-item-px: 0.625rem;
  --tc-floating-item-py: 0.375rem;
  --tc-floating-item-gap: 0.5rem;
  --tc-floating-min-w: 12.5rem;

  /* Semantic Gaps (Gestalt Proximity Scale) */
  --tc-gap-inline-micro: 0.25rem;    /* 4px - Icon + text / Badges */
  --tc-gap-inline-tight: 0.5rem;     /* 8px - Sibling buttons / Tags */
  --tc-gap-inline-base: 0.75rem;     /* 12px - Action groups */
  --tc-gap-stack-label: 0.375rem;    /* 6px - Vertical Label + Input */
  --tc-gap-stack-field: 1rem;        /* 16px - Between form fields */
  --tc-gap-stack-section: 1.5rem;    /* 24px - Between layout sections */
  --tc-gap-stack-hero: 2rem;         /* 32px - Between major page blocks */

  --tc-form-stack-gap: 1rem;
  --tc-form-label-gap: 0.375rem;
  --tc-card-p: 1.5rem;

  /* --- MOTION & ANIMATION --- */
  --tc-duration-instant: 100ms;
  --tc-duration-fast: 150ms;
  --tc-duration-normal: 200ms;

  --tc-ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
  --tc-ease-smooth: cubic-bezier(0.4, 0, 0.2, 1);

  /* ========================================================
     2. SEMANTIC TOKENS (Dark Mode Default)
     ======================================================== */

  /* GLOBAL ACCESSIBILITY */
  --focus-ring: var(--tc-brand-300);  /* Subtle focus ring — distinto mas não vibra como o CTA */
  --focus-offset: 2px;

  /* BRAND MARK (Laranjão Puro — Exclusivo de Marca)
     brand-500 (C=0.17, pico de chroma da escala) fica reservado ao logo/símbolo.
     Nenhum elemento de interface usa mais o C=0.17 puro — o teto de saturação
     da UI passa a ser brand-600 (C=0.15), preservando o laranjão como sinal
     de identidade, não de interação. */
  --brand-mark: var(--tc-brand-500); /* oklch(67% 0.17 53) — BrandSymbol / logo apenas */

  /* ACCENT HIERARCHY (Os Três Laranjas de Interface)
     brand-600 (C=0.15) → CTA hero / confirmação explícita (Checkbox, Switch)
     brand-400 (C=0.15) → Ícone anchor de orientação, hover de nav item
     brand-300 (C=0.12) → Focus ring, borda de sub-item ativo
  */
  --accent-action:  var(--tc-brand-600); /* oklch(58% 0.15 53) — Botão CTA, Checkbox */
  --accent-ui:      var(--tc-brand-400); /* oklch(74% 0.15 53) — Ícone anchor, hover nav */
  --accent-subtle:  var(--tc-brand-300); /* oklch(80% 0.12 53) — Focus ring, borda sub-item */

  /* BACKGROUNDS (Elevação por Luminância - Modelo Four Zero Three) */
  --bg-app: var(--tc-neutral-1000);              /* Canvas Base: L=14% */
  --bg-base: var(--tc-neutral-1000);             /* Canvas Base: L=14% */
  --bg-surface: var(--tc-neutral-950);           /* Cards / Sidebar / Tabelas: L=18% */
  --bg-surface-elevated: var(--tc-neutral-900);  /* Dropdowns / Menus / Popovers: L=22% */
  --bg-surface-modal: var(--tc-neutral-850);     /* Modais / Diálogos: L=26% */
  --bg-surface-hover: var(--tc-neutral-800);     /* Hover / Toast: L=30% */
  --surface-current: var(--bg-surface);          /* Contextual Surface Inheritance */

  /* PHYSICAL SURFACE HIGHLIGHT (Chanfro de luz superior 1px) */
  --surface-highlight: inset 0 1px 0 0 oklch(100% 0 0 / 0.07);

  /* Global Structural Semantics */
  --radius: var(--tc-radius-md);

  /* TEXT (Paired with Backgrounds) */
  --text-heading: var(--tc-neutral-50);   /* L=96% — pico de branco reservado a headings/valores métricos */
  --text-primary: var(--tc-neutral-100);  /* L=93% — off-white, evita halation */
  --text-secondary: var(--tc-neutral-300);
  --text-tertiary: var(--tc-neutral-500);
  --text-muted: var(--tc-neutral-600);
  --text-inverse: var(--tc-neutral-950);
  --text-brand: var(--tc-brand-400);

  /* BORDERS */
  --border-subtle: oklch(26% 0.010 53);
  --border-base: oklch(30% 0.012 53);
  --border-strong: oklch(34% 0.015 53);
  --border-elevated: oklch(34% 0.015 53);
  --border-focus: var(--accent-action);
  --border-gradient-start: oklch(100% 0 0 / 0.18);
  --border-gradient-mid: var(--border-base);
  --border-gradient-end: oklch(26% 0.010 53);
  --tc-input-inner-shadow: inset 1px 2px 3px 0 oklch(0% 0 0 / 0.40);

  /* ACTIONS / BUTTONS (Solid Paring) */
  --action-primary-bg: var(--accent-action);      /* CTA hero: brand-600 sólido */
  --action-primary-hover: oklch(63% 0.15 53);     /* meio-passo entre 600 e 500 — nunca toca C=0.17 */
  --action-primary-active: var(--tc-brand-700);
  --action-primary-fg: var(--tc-neutral-0);
  --btn-primary-border-start: var(--tc-brand-300);
  --btn-primary-border-mid: var(--tc-brand-600);
  --btn-primary-border-end: var(--tc-brand-700);

  --btn-destructive-border-start: oklch(62% 0.18 25);
  --btn-destructive-border-mid: var(--tc-danger-base);
  --btn-destructive-border-end: oklch(38% 0.16 25);

  --action-secondary-bg: var(--tc-neutral-800);
  --action-secondary-hover: var(--tc-neutral-700);
  --action-secondary-active: var(--tc-neutral-900);
  --action-secondary-fg: var(--tc-neutral-100);
  --btn-secondary-border-start: oklch(100% 0 0 / 0.28);
  --btn-secondary-border-mid: var(--tc-neutral-700);
  --btn-secondary-border-end: var(--tc-neutral-950);

  --action-subtle-bg: transparent;
  --action-subtle-hover: var(--tc-neutral-900);
  --action-subtle-active: var(--tc-neutral-800);
  --action-subtle-fg: var(--tc-neutral-300);

  /* STATUS SEMANTICS (Solid & Subtle Pairing) */
  --status-success-bg: var(--tc-success-base);
  --status-success-fg: var(--tc-success-fg);
  --status-success-subtle: var(--tc-success-subtle);
  --status-success-text: var(--tc-success-text);
  --status-success-border: var(--tc-success-base);

  --status-warning-bg: var(--tc-warning-base);
  --status-warning-fg: var(--tc-warning-fg);
  --status-warning-subtle: var(--tc-warning-subtle);
  --status-warning-text: var(--tc-warning-text);
  --status-warning-border: var(--tc-warning-base);

  --status-danger-bg: var(--tc-danger-base);
  --status-danger-fg: var(--tc-danger-fg);
  --status-danger-subtle: var(--tc-danger-subtle);
  --status-danger-text: var(--tc-danger-text);
  --status-danger-border: var(--tc-danger-base);

  --status-info-bg: var(--tc-info-base);
  --status-info-fg: var(--tc-info-fg);
  --status-info-subtle: var(--tc-info-subtle);
  --status-info-text: var(--tc-info-text);
  --status-info-border: var(--tc-info-base);

  /* TAG SEMANTICS (Solid & Subtle Pairing) */
  --tag-purple-bg: var(--tc-tag-purple-base);
  --tag-purple-fg: var(--tc-tag-purple-fg);
  --tag-purple-subtle: var(--tc-tag-purple-subtle);
  --tag-purple-text: var(--tc-tag-purple-text);
  --tag-purple-border: var(--tc-tag-purple-base);

  --tag-pink-bg: var(--tc-tag-pink-base);
  --tag-pink-fg: var(--tc-tag-pink-fg);
  --tag-pink-subtle: var(--tc-tag-pink-subtle);
  --tag-pink-text: var(--tc-tag-pink-text);
  --tag-pink-border: var(--tc-tag-pink-base);

  --tag-teal-bg: var(--tc-tag-teal-base);
  --tag-teal-fg: var(--tc-tag-teal-fg);
  --tag-teal-subtle: var(--tc-tag-teal-subtle);
  --tag-teal-text: var(--tc-tag-teal-text);
  --tag-teal-border: var(--tc-tag-teal-base);

  --tag-indigo-bg: var(--tc-tag-indigo-base);
  --tag-indigo-fg: var(--tc-tag-indigo-fg);
  --tag-indigo-subtle: var(--tc-tag-indigo-subtle);
  --tag-indigo-text: var(--tc-tag-indigo-text);
  --tag-indigo-border: var(--tc-tag-indigo-base);

  /* CHART SEMANTICS */
  --chart-1: var(--tc-chart-1);
  --chart-2: var(--tc-chart-2);
  --chart-3: var(--tc-chart-3);
  --chart-4: var(--tc-chart-4);
  --chart-5: var(--tc-chart-5);
  --chart-6: var(--tc-chart-6);

  /* SKELETON & SHIMMER (NN/g + OKLCH Model) */
  --skeleton-bg-base: oklch(21% 0.009 53);
  --skeleton-shimmer-highlight: oklch(25% 0.012 53);
  --skeleton-duration: 1.8s;
}

/* ========================================================
   3. LIGHT MODE OVERRIDES
   ======================================================== */
.light, [data-theme="light"] {
  color-scheme: light;
  /* BACKGROUNDS */
  --bg-app: oklch(97% 0.006 53);
  --bg-base: oklch(97% 0.006 53);
  --bg-surface: oklch(100% 0 0);
  --bg-surface-elevated: oklch(100% 0 0);
  --bg-surface-modal: oklch(100% 0 0);
  --bg-surface-hover: oklch(94% 0.006 53);

  /* PHYSICAL SURFACE HIGHLIGHT */
  --surface-highlight: none;

  /* TEXT */
  --text-heading: oklch(12% 0.010 53);
  --text-primary: oklch(18% 0.010 53);
  --text-secondary: oklch(42% 0.012 53);
  --text-tertiary: oklch(55% 0.014 53);
  --text-muted: oklch(55% 0.014 53);
  --text-inverse: oklch(99% 0.004 53);
  --text-brand: var(--tc-brand-600);

  /* BORDERS */
  --border-subtle: oklch(90% 0.008 53);
  --border-base: oklch(88% 0.008 53);
  --border-strong: oklch(84% 0.012 53);
  --border-elevated: oklch(84% 0.012 53);
  --border-focus: var(--accent-action);
  --border-gradient-start: var(--border-subtle);
  --border-gradient-mid: var(--border-base);
  --border-gradient-end: var(--border-strong);
  --tc-input-inner-shadow: inset 1px 2px 3px 0 oklch(0% 0 0 / 0.07);

  /* ACTIONS / BUTTONS */
  --action-primary-bg: var(--accent-action);
  --action-primary-hover: var(--tc-brand-700);
  --action-primary-active: var(--tc-brand-800);
  --action-primary-fg: var(--tc-neutral-0);

  --action-secondary-bg: var(--tc-neutral-100);
  --action-secondary-hover: var(--tc-neutral-200);
  --action-secondary-active: var(--tc-neutral-300);
  --action-secondary-fg: var(--tc-neutral-900);
  --btn-secondary-border-start: oklch(100% 0 0 / 0.95);
  --btn-secondary-border-mid: var(--tc-neutral-200);
  --btn-secondary-border-end: var(--tc-neutral-300);

  --action-subtle-bg: transparent;
  --action-subtle-hover: var(--tc-neutral-50);
  --action-subtle-active: var(--tc-neutral-100);
  --action-subtle-fg: var(--tc-neutral-700);

  /* STATUS SEMANTICS (Light versions) */
  --status-success-subtle: oklch(95% 0.02 145);
  --status-success-text: oklch(35% 0.1 145);

  --status-warning-subtle: oklch(95% 0.04 85);
  --status-warning-text: oklch(40% 0.1 85);

  --status-danger-subtle: oklch(95% 0.03 25);
  --status-danger-text: oklch(40% 0.15 25);

  --status-info-subtle: oklch(95% 0.03 240);
  --status-info-text: oklch(35% 0.1 240);

  /* TAG SEMANTICS (Light versions) */
  --tag-purple-subtle: oklch(95% 0.03 300);
  --tag-purple-text: oklch(35% 0.1 300);

  --tag-pink-subtle: oklch(95% 0.03 340);
  --tag-pink-text: oklch(35% 0.1 340);

  --tag-teal-subtle: oklch(95% 0.03 190);
  --tag-teal-text: oklch(35% 0.1 190);

  --tag-indigo-subtle: oklch(95% 0.03 270);
  --tag-indigo-text: oklch(35% 0.1 270);

  /* SKELETON (Light Mode) */
  --skeleton-bg-base: oklch(92% 0.006 53);
  --skeleton-shimmer-highlight: oklch(96% 0.004 53);
}

/* ========================================================
   PARAMETRIC DENSITY TOKENS (Enterprise Density Matrix)
   ======================================================== */
:root,
[data-density="default"] {
  --tc-density-mode: "default";
  --tc-table-row-h: 2.5rem;       /* 40px */
  --tc-table-cell-py: 0.625rem;   /* 10px */
  --tc-table-cell-px: 1rem;       /* 16px */
  --tc-input-h: 2.375rem;         /* 38px */
  --tc-input-px: 0.875rem;        /* 14px */
  --tc-input-py: 0.5rem;          /* 8px */
  --tc-card-p: 1.5rem;            /* 24px */
  --tc-form-stack-gap: 1.25rem;   /* 20px */
  --tc-density-font-size: 0.8125rem; /* 13px */
}

[data-density="compact"] {
  --tc-density-mode: "compact";
  --tc-table-row-h: 2rem;         /* 32px - Operational / Fiscal */
  --tc-table-cell-py: 0.25rem;    /* 4px */
  --tc-table-cell-px: 0.625rem;   /* 10px */
  --tc-input-h: 1.875rem;         /* 30px */
  --tc-input-px: 0.625rem;        /* 10px */
  --tc-input-py: 0.25rem;         /* 4px */
  --tc-card-p: 1rem;              /* 16px */
  --tc-form-stack-gap: 0.75rem;   /* 12px */
  --tc-density-font-size: 0.75rem;   /* 12px */
}

[data-density="comfortable"] {
  --tc-density-mode: "comfortable";
  --tc-table-row-h: 3rem;         /* 48px - Executive / Settings */
  --tc-table-cell-py: 0.875rem;   /* 14px */
  --tc-table-cell-px: 1.25rem;    /* 20px */
  --tc-input-h: 2.75rem;          /* 44px */
  --tc-input-py: 0.625rem;        /* 10px */
  --tc-input-px: 1rem;            /* 16px */
  --tc-card-p: 1.875rem;          /* 30px */
  --tc-form-stack-gap: 1.5rem;    /* 24px */
  --tc-density-font-size: 0.875rem;  /* 14px */
}

/* ========================================================
   PARAMETRIC DENSITY CASCADING OVERRIDES
   ======================================================== */

/* --------------------------------------------------------
   1. COMPACT MODE (Fiscal / Operacional / Alta Densidade)
   -------------------------------------------------------- */

/* Tables & DataGrids */
[data-density="compact"] table th {
  padding-top: 0.25rem !important;
  padding-bottom: 0.25rem !important;
  padding-left: 0.75rem !important;
  padding-right: 0.75rem !important;
  height: 2rem !important;
  font-size: 0.75rem !important;
}

[data-density="compact"] table td {
  padding-top: 0.25rem !important;
  padding-bottom: 0.25rem !important;
  padding-left: 0.75rem !important;
  padding-right: 0.75rem !important;
  height: 2rem !important;
  font-size: 0.75rem !important;
  line-height: 1.15rem !important;
}

[data-density="compact"] table td .rounded-full.w-8.h-8,
[data-density="compact"] table td [class*="w-8 h-8"] {
  width: 1.375rem !important;
  height: 1.375rem !important;
  font-size: 0.65rem !important;
}

[data-density="compact"] table td [class*="badge"],
[data-density="compact"] table td [class*="Badge"] {
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  font-size: 0.6875rem !important;
  height: 1.125rem !important;
}

/* Form Inputs & Selects: Only alter vertical bounds, preserving pl/pr icon offsets */
[data-density="compact"] input:not([type="checkbox"]):not([type="radio"]),
[data-density="compact"] select,
[data-density="compact"] [role="combobox"] {
  height: 2rem !important;
  min-height: 2rem !important;
  padding-top: 0.2rem !important;
  padding-bottom: 0.2rem !important;
  font-size: 0.75rem !important; /* 12px - WCAG 2.2 floor */
}

/* Cards & Metric Cards */
[data-density="compact"] .surface-card:not(aside),
[data-density="compact"] .metric-card {
  padding: 0.875rem 1rem !important;
}

[data-density="compact"] .metric-card [class*="text-2xl"],
[data-density="compact"] .metric-card [class*="text-3xl"] {
  font-size: 1.375rem !important;
  line-height: 1.625rem !important;
}

[data-density="compact"] .metric-card .my-3 {
  margin-top: 0.25rem !important;
  margin-bottom: 0.25rem !important;
}

/* Layout Stacks (Forms and Data Lists) */
[data-density="compact"] form.space-y-4 > :not([hidden]) ~ :not([hidden]),
[data-density="compact"] .form-group.space-y-4 > :not([hidden]) ~ :not([hidden]) {
  margin-top: 0.625rem !important;
}


/* --------------------------------------------------------
   2. COMFORTABLE MODE (Executivo / Telas Leves / Espaçoso)
   -------------------------------------------------------- */

/* Tables & DataGrids */
[data-density="comfortable"] table th {
  padding-top: 0.875rem !important;
  padding-bottom: 0.875rem !important;
  padding-left: 1.25rem !important;
  padding-right: 1.25rem !important;
  height: 3.25rem !important;
  font-size: 0.875rem !important;
}

[data-density="comfortable"] table td {
  padding-top: 0.875rem !important;
  padding-bottom: 0.875rem !important;
  padding-left: 1.25rem !important;
  padding-right: 1.25rem !important;
  height: 3.25rem !important;
  font-size: 0.875rem !important;
  line-height: 1.5rem !important;
}

[data-density="comfortable"] table td .rounded-full.w-8.h-8,
[data-density="comfortable"] table td [class*="w-8 h-8"] {
  width: 2.25rem !important;
  height: 2.25rem !important;
  font-size: 0.8125rem !important;
}

/* Form Inputs & Selects: Only alter vertical bounds, preserving pl/pr icon offsets */
[data-density="comfortable"] input:not([type="checkbox"]):not([type="radio"]),
[data-density="comfortable"] select,
[data-density="comfortable"] [role="combobox"] {
  height: 2.75rem !important;
  min-height: 2.75rem !important;
  padding-top: 0.5rem !important;
  padding-bottom: 0.5rem !important;
  font-size: 0.875rem !important;
}

/* Cards & Metric Cards */
[data-density="comfortable"] .surface-card:not(aside),
[data-density="comfortable"] .metric-card {
  padding: 1.875rem 2rem !important;
}

[data-density="comfortable"] .metric-card [class*="text-2xl"],
[data-density="comfortable"] .metric-card [class*="text-3xl"] {
  font-size: 2.25rem !important;
  line-height: 2.5rem !important;
}

[data-density="comfortable"] .metric-card .my-3 {
  margin-top: 1rem !important;
  margin-bottom: 1rem !important;
}

