/* ========================================================
   Skeleton Shimmer (NN/g + OKLCH Model)
   ======================================================== */
@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

.skeleton-shimmer {
  background: linear-gradient(
    90deg,
    var(--skeleton-bg-base) 0%,
    var(--skeleton-shimmer-highlight) 50%,
    var(--skeleton-bg-base) 100%
  );
  background-size: 200% 100%;
  animation: shimmer var(--skeleton-duration) cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-shimmer {
    animation: none !important;
    background: var(--skeleton-bg-base) !important;
  }
}

/* ========================================================
   Enterprise Layout & Container Query Utilities
   ======================================================== */
.kpi-dashboard-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr));
  gap: 1rem;
}

.cq-card-container {
  container-type: inline-size;
  container-name: card;
}

@container card (max-width: 320px) {
  .cq-stack-on-narrow {
    flex-direction: column !important;
    align-items: flex-start !important;
  }
  .cq-hide-on-narrow {
    display: none !important;
  }
}
